import os

config = {'model_version': os.environ.get('MODEL_VERSION', 'dev'), 'port': int(os.environ.get('PORT', '8000'))}
print(config)

def parse(version):
    return tuple(int(part) for part in version.split('.'))

print(parse('1.4.0') < parse('1.10.0'))

def health(model_loaded, db_ready):
    return {'live': True, 'ready': model_loaded and db_ready}

print(health(True, False))

